836	async function wait(a,ms){
837	 var end=performance.now()+ms;
838	 while(a.chat||performance.now()<end)await sleep(a.chat?250:Math.max(16,Math.min(250,end-performance.now())));
839	}
840	var awayCount=0;
841	async function life(a,delay){
842	 await wait(a,delay);
843	 var eager=delay<3000;
844	 for(;;){
845	  pose(a,'sit');a.st={k:'desk'};
846	  if(Math.random()<.6){a.cur=pick(a.work);say(a,a.cur)}
847	  await wait(a,eager?rand(900,2200):rand(6000,15000));
848	  if(!eager&&(awayCount>=5||Math.random()<.3))continue;
849	  eager=false;
850	  awayCount++;a.away=true;
851	  var dest,host=null;
852	  if(Math.random()<.45){
853	   var others=TEAM.filter(function(b){return b!==a&&!b.away});
854	   dest=visitSpot(pick(others));host=dest.host;
855	  }else dest=pick(POI);
856	  var poi=host?null:dest;
857	  var jit=dest.host?0:rand(-12,12);dest={pt:[dest.pt[0]+jit,dest.pt[1]],aisle:dest.aisle,ax:dest.ax,pre:dest.pre,lines:dest.lines,host:dest.host};
858	  var pts=route(a,dest);
859	  a.cur=host?'conversando com '+host.n:'dando uma pausa';
860	  a.st={k:'going',host:host,poi:poi};
861	  await walk(a,pts);
862	  pose(a,'idle');a.el.classList.remove('flip');
863	  a.st={k:'there',host:host,poi:poi};
864	  if(host){say(a,pick(VISIT));if(!host.away)setTimeout(function(){say(host,pick(REPLY))},1600)}
865	  else say(a,pick(dest.lines));
866	  await wait(a,rand(3800,6500));
867	  var backPts=pts.slice(0,-1).reverse();backPts.push(a.seat.slice());
868	  a.st={k:'back'};
869	  await walk(a,backPts);
870	  a.el.classList.remove('flip');
871	  a.away=false;awayCount--;
872	 }
873	}
