async function wait(a,ms){
 var end=performance.now()+ms;
 while(a.chat||performance.now()<end)await sleep(a.chat?250:Math.max(16,Math.min(250,end-performance.now())));
}
var awayCount=0;
async function life(a,delay){
 await wait(a,delay);
 var eager=delay<3000;
 for(;;){
  pose(a,'sit');a.st={k:'desk'};
  if(Math.random()<.6){a.cur=pick(a.work);say(a,a.cur)}
  await wait(a,eager?rand(900,2200):rand(6000,15000));
  if(!eager&&(awayCount>=5||Math.random()<.3))continue;
  eager=false;
  awayCount++;a.away=true;
  var dest,host=null;
  if(Math.random()<.45){
   var others=TEAM.filter(function(b){return b!==a&&!b.away});
   dest=visitSpot(pick(others));host=dest.host;
  }else dest=pick(POI);
  var poi=host?null:dest;
  var jit=dest.host?0:rand(-12,12);dest={pt:[dest.pt[0]+jit,dest.pt[1]],aisle:dest.aisle,ax:dest.ax,pre:dest.pre,lines:dest.lines,host:dest.host};
  var pts=route(a,dest);
  a.cur=host?'conversando com '+host.n:'dando uma pausa';
  a.st={k:'going',host:host,poi:poi};
  await walk(a,pts);
