 var b=a.bag[key];
 if(!b||!b.length||b.src!==arr){
  b=arr.map(function(_,i){return i});
  for(var i=b.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),x=b[i];b[i]=b[j];b[j]=x}
  if(b.length>1&&arr[b[b.length-1]]===a.lp[key]){var y=b[0];b[0]=b[b.length-1];b[b.length-1]=y}
  b.src=arr;a.bag[key]=b;
 }
 var s=arr[b.pop()];a.lp[key]=s;return s;
}
