 a.mem.push(t);if(a.mem.length>8)a.mem.shift();
 var pend=a.pend,turns=a.turns||0;a.turns=turns+1;
 var hi=RX.oi.test(t),noite=RX.noite.test(t),dia=RX.dia.test(t),q=RX.q.test(t),tp=topicOf(t);
 if(pend&&RX.sim.test(t))cat='sim';
 else if(pend&&RX.nao.test(t))cat='nao';
 else if(RX.faz.test(t))cat='faz';
